'use strict';
// Certificate artwork and layout checks in a disposable native review project.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),project=path.resolve(root,'../.rural-quiz-runtime/theme-content-review'),out=path.join(root,'qa/certificate-20261021');fs.mkdirSync(out,{recursive:true});fs.mkdirSync(path.join(out,'artwork'),{recursive:true});const checks=[];
async function call(tool,args=[]){return new Promise((resolve,reject)=>{const c=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',project,...args]);let text='';c.stdout.on('data',b=>text+=b);c.stderr.on('data',b=>text+=b);const t=setTimeout(()=>{c.kill();reject(Error(tool+' timeout'));},45000);c.on('close',code=>{clearTimeout(t);let r;try{r=JSON.parse(text.slice(text.indexOf('{'),text.lastIndexOf('}')+1));}catch{return reject(Error(text.slice(0,800)));}if(code||!r.ok||r.result?.success===false)return reject(Error(r.message||r.result?.error||text.slice(0,800)));resolve(r.result);});});}
async function evaluate(fn){let r=await call('automation_evaluate',['--fn-source',fn]);for(let i=0;i<6&&r&&r.result!==undefined;i++)r=r.result;return r;}
function css(s,size){return s.replace(/@media\s*\(max-width:(\d+)px\)/g,(_,n)=>size.w<=Number(n)?'@media(min-width:0px)':'@media(max-width:0px)').replace(/([\d.]+)rpx\b/g,(_,n)=>(Number(n)*size.w/750)+'px').replace(/([\d.]+)v([wh])\b/g,(_,n,a)=>(Number(n)*(a==='w'?size.w:size.h)/100)+'px');}
function stage(size){for(const dir of ['pages/game','components/game-button','components/mascot-actor'])for(const name of fs.readdirSync(path.join(root,'miniprogram',dir)).filter(x=>x.endsWith('.wxss'))){let s=css(fs.readFileSync(path.join(root,'miniprogram',dir,name),'utf8'),size);if(dir==='pages/game'&&name==='index.wxss')s+='\n.game-device{width:'+size.w+'px!important;height:'+size.h+'px!important;max-width:none!important;margin:0!important;transform-origin:0 0}\n';fs.writeFileSync(path.join(project,'miniprogram',dir,name),s);}
 const info={windowWidth:size.w,windowHeight:size.h,screenWidth:size.w,screenHeight:size.h,statusBarHeight:size.status,safeArea:{top:size.status,left:0,right:size.w,bottom:size.h-size.safe,width:size.w,height:size.h-size.safe-size.status}},menu={left:size.w-94,right:size.w-7,top:size.status+6,bottom:size.status+38,width:87,height:32};
 const s=fs.readFileSync(path.join(root,'miniprogram/pages/game/index.js'),'utf8'),from='const i=wx.getWindowInfo?wx.getWindowInfo():wx.getSystemInfoSync(),m=homeLayout.metrics(i,wx.getMenuButtonBoundingClientRect?wx.getMenuButtonBoundingClientRect():null,skin.gameId);';assert(s.includes(from));fs.writeFileSync(path.join(project,'miniprogram/pages/game/index.js'),s.replace(from,'const i='+JSON.stringify(info)+',m=homeLayout.metrics(i,'+JSON.stringify(menu)+',skin.gameId);'));
}
function save(){fs.writeFileSync(path.join(out,'native-checks.json'),JSON.stringify({passed:checks.every(c=>c.passed),scope:'Actual WeChat canvas PNG, native image preview and constrained native containers. Host simulator 390x844, not physical phone or album permission acceptance. Review certificate records are isolated.',checks},null,2)+'\n');}
const rects="const sels=['.game-device','.panel-body','.panel-footer','.certificate-paper','.certificate-preview','.certificate-save-note','.state-block','#footer-primary','#footer-secondary'],q=wx.createSelectorQuery();sels.forEach(s=>q.selectAll(s).boundingClientRect());const rect=await new Promise(r=>q.exec(rows=>r(Object.fromEntries(sels.map((s,i)=>[s,rows[i]])))));";
async function measure(){return evaluate('async function(){const p=getCurrentPages().slice(-1)[0];await p.prepareCertificate();await new Promise(r=>setTimeout(r,100));'+rects+'const info=await new Promise((resolve,reject)=>wx.getImageInfo({src:p.data.certificateImage,success:resolve,fail:reject}));return {theme:p.data.skin.gameId,error:p.data.certificateImageError,file:p.data.certificateImage,width:info.width,height:info.height,ratio:p.data.certificateImageRatio,rect};}');}
async function artwork(theme){
 // Read the PNG through the documented WeChat file API in bounded chunks;
 // the CLI truncates a single large base64 response.
 const info=await evaluate('function(){const p=getCurrentPages().slice(-1)[0];return {length:wx.getFileSystemManager().readFileSync(p.data.certificateImage,"base64").length};}');
 let encoded='';for(let offset=0;offset<info.length;offset+=30000){const part=await evaluate('function(){const p=getCurrentPages().slice(-1)[0];return {chunk:wx.getFileSystemManager().readFileSync(p.data.certificateImage,"base64").slice('+offset+','+(offset+30000)+')};}');encoded+=part.chunk;}
 assert.equal(encoded.length,info.length);const b=Buffer.from(encoded,'base64');assert(b.slice(1,4).toString()==='PNG');fs.writeFileSync(path.join(out,'artwork',theme+'-荣誉证书.png'),b);return {file:'artwork/'+theme+'-荣誉证书.png',bytes:b.length,width:b.readUInt32BE(16),height:b.readUInt32BE(20)};
}
async function screenshot(name,size){const scale=Math.min(1,390/size.w,844/size.h);if(scale<1){const d=await call('automation_page_action',['--action','getData','--data-path','shellStyle']);await call('automation_page_action',['--action','setData','--patch',JSON.stringify({shellStyle:d.data+';transform:scale('+scale+');'})]);}await call('simulator_screenshot',['--path',path.join(out,name),'--optimize','false','--wait-for-selector','.certificate-preview']);}
(async()=>{try{
 for(const size of [{w:320,h:568,status:20,safe:0},{w:375,h:812,status:44,safe:34},{w:430,h:932,status:59,safe:34}]){
 stage(size);await call('simulator_refresh');await call('automation_page_action',['--action','getData','--data-path','route','--wait-for-selector','.game-device']);
 for(const theme of ['ecology','red','culture','industry']){
 await call('automation_navigate',['--action','reLaunch','--url','/pages/game/index?theme='+theme+'&review=1&controls=0&scenario=certificate']);
 const d=await measure(),issues=[],test=(ok,label)=>{if(!ok)issues.push(label);},image=d.rect['.certificate-preview'][0],body=d.rect['.panel-body'][0];
 test(!d.error&&d.width===900&&d.height===1280,'full-resolution certificate generated');test(image.width>200&&image.left>=body.left&&image.right<=body.right,'certificate inside scroll width');test(Math.abs(image.height/image.width-d.height/d.width)<.02,'preview keeps exported image ratio');test(d.rect['.panel-footer'][0].bottom<=size.h-size.safe+1,'footer safe area');test(d.rect['#footer-primary'][0].height>=44&&d.rect['#footer-secondary'][0].height>=44,'save and share touch targets');
 const art=size.w===375?await artwork(theme):undefined;
 const top=theme+'-'+size.w+'-certificate-top.png';await screenshot(top,size);
 // Restore scale before measuring the scroll-to-end geometry.
 if(size.w===430){const p=await call('automation_page_action',['--action','getData','--data-path','shellStyle']);await call('automation_page_action',['--action','setData','--patch',JSON.stringify({shellStyle:p.data.replace(/;transform:scale\([^)]*\);/,'')})]);}
 await call('automation_element_action',['--action','scrollTo','--selector','.panel-body','--x','0','--y','9999']);const end=await measure();test(end.rect['.certificate-preview'][0].bottom<=end.rect['.panel-body'][0].bottom+1,'certificate signature reachable above footer');
 const bottom=theme+'-'+size.w+'-certificate-bottom.png';await screenshot(bottom,size);checks.push({theme,size,passed:!issues.length,issues,dimensions:{width:d.width,height:d.height},rect:d.rect,scrolled:end.rect,artwork:art,screenshots:[top,bottom]});save();console.log((issues.length?'FAIL ':'PASS ')+theme+' '+size.w+' '+issues.join(', '));
 }
 if(size.w===375){for(const theme of ['ecology','red','culture','industry']){await call('automation_navigate',['--action','reLaunch','--url','/pages/game/index?theme='+theme+'&review=1&controls=0&scenario=home&route=certificate']);const d=await evaluate('function(){const p=getCurrentPages().slice(-1)[0];return {certificate:p.data.certificate,image:p.data.certificateImage,route:p.data.route,earned:p.data.certificates.length};}');assert.equal(d.route,'certificate');assert.equal(d.certificate,null);assert.equal(d.image,'');assert.equal(d.earned,0);checks.push({theme,size,state:'not-earned',passed:true});save();}
 // Long recipient/description in presentation only; no stored record or service mutation.
 await call('automation_navigate',['--action','reLaunch','--url','/pages/game/index?theme=ecology&review=1&controls=0&scenario=certificate']);await call('automation_evaluate',['--fn-source','async function(){const p=getCurrentPages().slice(-1)[0];p.setData({certificate:Object.assign({},p.data.certificate,{userName:"湖南乡村阅读文化探索者陈小禾ABCDEFGHIJKLMNOPQRSTUVWXYZ",description:"在自然观察与生态文化学习中积累知识，珍惜山水，保护家园。".repeat(4)})});await p.prepareCertificate();return {ready:!!p.data.certificateImage};}']);const long=await measure();assert(long.height>1280);await artwork('ecology-long');checks.push({theme:'ecology',size,state:'long-recipient',passed:true,dimensions:{width:long.width,height:long.height}});save();
 }
 }
 }finally{for(const dir of ['pages/game','components/game-button','components/mascot-actor'])for(const file of fs.readdirSync(path.join(root,'miniprogram',dir)).filter(x=>x.endsWith('.wxss')))fs.copyFileSync(path.join(root,'miniprogram',dir,file),path.join(project,'miniprogram',dir,file));fs.copyFileSync(path.join(root,'miniprogram/pages/game/index.js'),path.join(project,'miniprogram/pages/game/index.js'));await call('simulator_refresh');}
 if(checks.some(c=>!c.passed))process.exitCode=1;else fs.rmSync(path.join(out,'native-error.txt'),{force:true});
})().catch(e=>{fs.writeFileSync(path.join(out,'native-error.txt'),e.stack);console.error(e);process.exitCode=1;});
